import { test, beforeEach, afterEach } from 'node:test';
import assert from 'node:assert/strict';
import { testServer } from './helpers.js';
let server, owner, member, guest, org, project, memberId, guestId;
beforeEach(async () => {
  server = await testServer();
  owner = server.agent(); member = server.agent(); guest = server.agent();
  await owner('POST', '/auth/signup', { name: 'Owner', email: 'owner@project.test', password: 'correct-horse-123' });
  memberId = (await member('POST', '/auth/signup', { name: 'Member', email: 'member@project.test', password: 'correct-horse-123' })).data.user.id;
  guestId = (await guest('POST', '/auth/signup', { name: 'Guest', email: 'guest@project.test', password: 'correct-horse-123' })).data.user.id;
  org = (await owner('POST', '/orgs', { name: 'Planning' })).data.organization;
  await owner('POST', '/orgs/' + org.id + '/members', { userId: memberId, role: 'member' });
  await owner('POST', '/orgs/' + org.id + '/members', { userId: guestId, role: 'guest' });
  const created = await owner('POST', '/orgs/' + org.id + '/projects', { key: 'PL', name: 'Planning', description: 'Plan the work' });
  assert.equal(created.status, 201, JSON.stringify(created.data));
  project = created.data.project;
});
afterEach(async () => { await server.close(); });
test('project creation stores default ordered workflow and metadata', async () => {
  assert.equal(project.key, 'PL'); assert.equal(project.nextIssueNumber, 1);
  assert.deepEqual(project.statuses.map(status => status.category), ['todo', 'active', 'done']);
  const read = await owner('GET', '/projects/' + project.id);
  assert.equal(read.data.project.description, 'Plan the work'); assert.equal(read.data.permissions.manage, true);
});
test('project keys are case-insensitively unique within an organization', async () => {
  const result = await owner('POST', '/orgs/' + org.id + '/projects', { key: 'pl', name: 'Duplicate' });
  assert.equal(result.status, 409);
  const second = (await owner('POST', '/orgs', { name: 'Second' })).data.organization;
  assert.equal((await owner('POST', '/orgs/' + second.id + '/projects', { key: 'PL', name: 'Other org' })).status, 201);
});
test('members read projects but cannot create or update their configuration', async () => {
  assert.equal((await member('GET', '/projects/' + project.id)).status, 200);
  assert.equal((await member('PATCH', '/projects/' + project.id, { name: 'No' })).status, 403);
  assert.equal((await member('POST', '/orgs/' + org.id + '/projects', { key: 'NO', name: 'No' })).status, 403);
});
test('guest project access is filtered before cursor pagination', async () => {
  const visible = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'VS', name: 'Visible' })).data.project;
  await owner('POST', '/projects/' + visible.id + '/guests', { userId: guestId });
  const result = await guest('GET', '/orgs/' + org.id + '/projects?limit=1');
  assert.equal(result.status, 200); assert.deepEqual(result.data.items.map(row => row.id), [visible.id]); assert.equal(result.data.nextCursor, null);
  assert.equal((await guest('GET', '/projects/' + project.id)).status, 403);
});
test('project patch persists description and archive with explicit restore', async () => {
  assert.equal((await owner('PATCH', '/projects/' + project.id, { name: 'Roadmap', description: 'Next quarter', archived: true })).data.project.archived, true);
  assert.equal((await owner('GET', '/projects')).data.items.length, 0);
  assert.equal((await owner('GET', '/projects?archived=true')).data.items[0].name, 'Roadmap');
  await owner('PATCH', '/projects/' + project.id, { archived: false });
  assert.equal((await owner('GET', '/projects')).data.items[0].description, 'Next quarter');
});
test('workflow replacement preserves identifiers when reordering and renaming', async () => {
  const [todo, active, done] = project.statuses;
  const statuses = [done, todo, { ...active, name: 'In progress' }].map(({ id, name, category }) => ({ id, name, category }));
  const result = await owner('PUT', '/projects/' + project.id + '/workflow', { statuses });
  assert.equal(result.status, 200, JSON.stringify(result.data));
  assert.deepEqual(result.data.statuses.map(row => row.id), [done.id, todo.id, active.id]);
  assert.deepEqual(result.data.statuses.map(row => row.position), [0, 1, 2]);
});
test('workflow validation rejects duplicate names and foreign status IDs atomically', async () => {
  const other = (await owner('POST', '/orgs/' + org.id + '/projects', { key: 'OT', name: 'Other' })).data.project;
  const statuses = [{ id: other.statuses[0].id, name: 'Todo', category: 'todo' }, { name: 'Done', category: 'done' }];
  assert.equal((await owner('PUT', '/projects/' + project.id + '/workflow', { statuses })).status, 422);
  assert.deepEqual((await owner('GET', '/projects/' + project.id + '/workflow')).data.statuses, project.statuses);
});
test('workflow cannot remove a status holding an issue', async () => {
  const created = await owner('POST', '/projects/' + project.id + '/issues', { title: 'Keep status', statusId: project.statuses[0].id });
  assert.equal(created.status, 201, JSON.stringify(created.data));
  const statuses = [{ name: 'Ready', category: 'todo' }, { id: project.statuses[2].id, name: 'Done', category: 'done' }];
  assert.equal((await owner('PUT', '/projects/' + project.id + '/workflow', { statuses })).status, 409);
});
test('numbered project keys cannot be changed accidentally', async () => {
  assert.equal((await owner('POST', '/projects/' + project.id + '/issues', { title: 'Issue' })).status, 201);
  assert.equal((await owner('PATCH', '/projects/' + project.id, { key: 'NEW' })).status, 409);
});
test('project deletion removes guest grants and denies later reads', async () => {
  await owner('POST', '/projects/' + project.id + '/guests', { userId: guestId });
  assert.equal((await owner('DELETE', '/projects/' + project.id)).status, 200);
  assert.equal(server.ctx.db.prepare('SELECT count(*) AS n FROM project_guests WHERE project_id=?').get(project.id).n, 0);
  assert.equal((await owner('GET', '/projects/' + project.id)).status, 404);
});
test('project mutation emits complete before and after event summaries', async () => {
  const events = []; server.ctx.bus.subscribe(event => events.push(event));
  await owner('PATCH', '/projects/' + project.id, { name: 'New name' });
  const event = events.find(event => event.entityType === 'project');
  assert.equal(event.orgId, org.id); assert.equal(event.projectId, project.id); assert(event.actorId && event.time);
  assert.equal(event.before.name, 'Planning'); assert.equal(event.after.name, 'New name'); assert.equal(event.after.statuses.length, 3);
});
test('project validation uses stable 422 details and malformed cursor is rejected', async () => {
  const result = await owner('PATCH', '/projects/' + project.id, { archived: 'yes' });
  assert.equal(result.status, 422); assert(result.data.error.details.archived);
  assert.equal((await owner('GET', '/projects?cursor=invalid')).status, 422);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { projectInput, workflowInput, projectKey } from '../src/schemas/project.js';
test('project key normalizes case and whitespace', () => {
  assert.equal(projectKey('  crew42  '), 'CREW42');
});
test('project key rejects punctuation and leading digits', () => {
  for (const key of ['1CREW', 'C-R', 'X', 'ABCDEFGHIJKLMNOP']) assert.throws(() => projectKey(key), { code: 'VALIDATION' });
});
test('project patch rejects unknown fields and nonboolean archive', () => {
  assert.throws(() => projectInput({ owner: 'person' }, { partial: true }), { status: 422 });
  assert.throws(() => projectInput({ archived: 'false' }, { partial: true }), { status: 422 });
});
test('workflow assigns contiguous positions without changing identifiers', () => {
  assert.deepEqual(workflowInput({ statuses: [
    { id: 'done', name: 'Done', category: 'done' },
    { id: 'todo', name: 'Ready', category: 'todo' }
  ] }).map(row => [row.id, row.position]), [['done', 0], ['todo', 1]]);
});
test('workflow requires todo and done categories', () => {
  assert.throws(() => workflowInput({ statuses: [{ name: 'A', category: 'active' }, { name: 'B', category: 'done' }] }), { status: 422 });
});
test('workflow rejects duplicate names and identifiers', () => {
  assert.throws(() => workflowInput({ statuses: [{ name: 'Todo', category: 'todo' }, { name: 'todo', category: 'done' }] }), { status: 422 });
  assert.throws(() => workflowInput({ statuses: [{ id: 'same', name: 'Todo', category: 'todo' }, { id: 'same', name: 'Done', category: 'done' }] }), { status: 422 });
});
test('project input preserves description content and accepts partial archive', () => {
  assert.deepEqual(projectInput({ archived: false }, { partial: true }), { archived: false });
  assert.equal(projectInput({ key: 'CR', name: 'Crew', description: 'Ship work' }).description, 'Ship work');
});
